// HMAC-SHA256 Signature Verification
// Rejects requests with invalid or stale signatures.

const crypto = require('crypto');

const secret = $env.N8N_SHARED_SECRET || 'change-me';
const headers = $input.first().headers || {};
const body = $input.first().json;

const signature = headers['x-CorpConnect-signature'] || '';
const timestamp = headers['x-CorpConnect-timestamp'] || '';

// Replay window: reject if older than 5 minutes
const age = Math.floor(Date.now() / 1000) - Number(timestamp);
if (age > 300 || age < -60) {
  throw new Error(`Replay rejected: timestamp age=${age}s`);
}

const message = `${body.ruleId}:${body.trigger}:${body.orgId}:${timestamp}`;
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(message).digest('hex');

if (!crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature))) {
  throw new Error('Invalid HMAC signature');
}

return [{ json: body }];

